#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
ACCOUNT=/home/rbxfxmfd
HTACCESS="$ACCOUNT/public_html/.htaccess"
NODE="$ACCOUNT/.local/node/node-v22.23.2-linux-x64/bin/node"
export PATH="$(dirname "$NODE"):$PATH"
export NEXT_TELEMETRY_DISABLED=1
[[ -x "$NODE" && -f "$HTACCESS" ]] || { echo 'EXPECTED_SERVER_LAYOUT_MISSING'; exit 1; }
HTACCESS="$HTACCESS" "$NODE" <<'JS'
const fs=require('fs'),s=fs.lstatSync(process.env.HTACCESS);
if(!s.isFile()||s.uid!==process.getuid()||(s.mode&0o777)!==0o644)throw Error('HTACCESS_MUST_BE_OWNED_REGULAR_FILE_MODE_644; public unchanged');
console.log('HTACCESS_INITIAL_MODE=644');
JS
LIVE=$(HTACCESS="$HTACCESS" "$NODE" <<'JS'
const fs=require('fs');const text=fs.readFileSync(process.env.HTACCESS,'utf8');
const roots=[...text.matchAll(/^\s*PassengerAppRoot\s+"([^"]+)"\s*$/gm)];
if(roots.length!==1||!/^\/home\/rbxfxmfd\/xclip-[^\r\n]+\/runtime$/.test(roots[0][1]))throw Error('UNEXPECTED_APP_ROOT');
console.log(roots[0][1]);
JS
)
[[ -f "$LIVE/server.js" && -f "$LIVE/.env.production" && -f "$LIVE/.next/BUILD_ID" ]] || { echo 'LIVE_RUNTIME_LAYOUT_MISSING'; exit 1; }
DEPLOY_LOCK="$ACCOUNT/.xclip-production-deploy.lock"
mkdir "$DEPLOY_LOCK" 2>/dev/null || { echo 'DEPLOYMENT_LOCK_EXISTS; another run or interrupted run needs checking'; exit 1; }
CHECK_PID=''
STATE_LOCK=''
STATE_LOCK_ID=''
[[ ! -e "$ACCOUNT/.xclip-free-download-deploy.lock" ]] || { echo "OLDER_DEPLOYMENT_LOCK_EXISTS"; rmdir "$DEPLOY_LOCK"; exit 1; }
cleanup() {
 if [[ -n "$CHECK_PID" ]]; then kill "$CHECK_PID" 2>/dev/null || true; fi
 if [[ -n "$STATE_LOCK" && -d "$STATE_LOCK" && "$(stat -c '%d:%i' "$STATE_LOCK")" == "$STATE_LOCK_ID" ]]; then rmdir "$STATE_LOCK" 2>/dev/null || true; fi
 rmdir "$DEPLOY_LOCK" 2>/dev/null || true
}
trap cleanup EXIT
HTACCESS_INITIAL_HASH=$(sha256sum "$HTACCESS" | cut -d " " -f 1)
LIVE_BUILD_ID=$(cat "$LIVE/.next/BUILD_ID")
SOURCE=$(ACCOUNT="$ACCOUNT" LIVE="$LIVE" "$NODE" <<'JS'
const fs=require('fs'),path=require('path');const account=process.env.ACCOUNT;const id=fs.readFileSync(path.join(process.env.LIVE,'.next/BUILD_ID'),'utf8').trim();
const recorded=path.join(process.env.LIVE,'DEPLOY_SOURCE');const activeSource=fs.existsSync(recorded)?fs.readFileSync(recorded,'utf8').trim():null;
const candidates=activeSource?[activeSource]:process.env.XCLIP_SOURCE?[process.env.XCLIP_SOURCE]:fs.readdirSync(account).flatMap(name=>[path.join(account,name),path.join(account,name,'source')]);
const matches=candidates.filter(p=>{try{return fs.existsSync(path.join(p,'app/components/RankingClient.tsx'))&&fs.existsSync(path.join(p,'package.json'))&&fs.readFileSync(path.join(p,'.next/BUILD_ID'),'utf8').trim()===id;}catch{return false;}});
if(!matches.length)throw Error('MATCHING_LIVE_BUILD_SOURCE_NOT_FOUND; public site unchanged. Share this error to locate the source before deployment.');
matches.sort((a,b)=>fs.statSync(path.join(b,'.next/BUILD_ID')).mtimeMs-fs.statSync(path.join(a,'.next/BUILD_ID')).mtimeMs);console.log(matches[0]);
JS
)
[[ -d "$SOURCE/node_modules/typescript" ]] || { echo 'MATCHING_SOURCE_DEPENDENCIES_MISSING'; exit 1; }
STAGE=$(mktemp -d "$ACCOUNT/xclip-registration-recovery1000-20261014.XXXXXX")
mkdir "$STAGE/source" "$STAGE/runtime" "$STAGE/installer"
printf 'MATCHING_LIVE_SOURCE=%s\nSTAGING_DIRECTORY=%s\n' "$SOURCE" "$STAGE"
# Copy the source for the actual LIVE build, including dependencies, without its secrets/caches.
tar -C "$SOURCE" --exclude='./.next' --exclude='./.git' --exclude='./.env*' --exclude='./.local-admin' --exclude='./artifacts' -cf - . | tar -C "$STAGE/source" -xf -
base64 -d > "$STAGE/feature.tar.gz" <<'PAYLOAD'
