printf '%s  %s\n' 'f1c290542548e3c982a38394a33f8a8d952552dc54914830629fabc42304ee5b' "$STAGE/feature.tar.gz" | sha256sum -c - >/dev/null
tar -C "$STAGE/installer" -xzf "$STAGE/feature.tar.gz"
touch "$STAGE/source/.xclip-production-staging"
"$NODE" "$STAGE/installer/install.cjs" "$STAGE/source"
LIVE="$LIVE" "$NODE" --env-file="$LIVE/.env.production" <<'JS'
const path=require('path'),os=require('os');
const state=process.env.XCLIP_DOWNLOAD_STATE_DIR||path.join(os.homedir(),'.xclip-download');
if(!path.isAbsolute(state))throw Error('DOWNLOAD_STATE_DIR_MUST_BE_ABSOLUTE; live unchanged');
const normalized=path.resolve(state),live=path.resolve(process.env.LIVE);
if(normalized===live||normalized.startsWith(live+path.sep))throw Error('DOWNLOAD_STATE_DIR_INSIDE_RUNTIME; live unchanged. Preserve state outside runtime before deployment.');
const authorDirectory=process.env.XCLIP_AUTHOR_STATE_DIR||path.join(os.homedir(),'.xclip-author-status');
if(!path.isAbsolute(authorDirectory)||path.resolve(authorDirectory)===live||path.resolve(authorDirectory).startsWith(live+path.sep))throw Error('AUTHOR_STATE_DIR_MUST_BE_DURABLE; public unchanged');
const freeDir=process.env.XCLIP_FREE_CURATED_STATE_DIR||path.join(os.homedir(),'.xclip-free-curated');
if(!path.isAbsolute(freeDir)||path.resolve(freeDir)===live||path.resolve(freeDir).startsWith(live+path.sep))throw Error('FREE_CURATED_STATE_DIR_MUST_BE_DURABLE');
const feed=process.env.XCLIP_RANKING_FEED_STATE_DIR||path.join(os.homedir(),'.xclip-ranking-feed');if(!path.isAbsolute(feed)||path.resolve(feed)===live||path.resolve(feed).startsWith(live+path.sep))throw Error('RANKING_STATE_MUST_BE_DURABLE');
console.log('DURABLE_DOWNLOAD_STATE_OK; no secret values printed');
JS
cp "$LIVE/.env.production" "$STAGE/source/.env.production"
chmod 600 "$STAGE/source/.env.production"
cd "$STAGE/source"
# Matching existing standalone configuration is preserved.
"$NODE" -e 'const fs=require("fs");const f=["next.config.ts","next.config.js","next.config.mjs"].find(f=>fs.existsSync(f));if(!f||!fs.readFileSync(f,"utf8").includes("standalone"))throw Error("STANDALONE_CONFIG_NOT_FOUND; live unchanged");'
node scripts/test-registration-session.cjs
node scripts/test-curated-common.cjs
node scripts/test-author-status.cjs
node scripts/test-free-curated-timeline.cjs
node scripts/test-fx-curated-patrol.cjs
node scripts/test-patrol-continuation.cjs
node scripts/test-monitor-jitter.cjs
node scripts/test-x-curated-hybrid.cjs
node scripts/test-free-curated-dashboard.cjs
node scripts/test-free-curated-production.cjs
node scripts/test-availability-monitor.cjs
node scripts/test-availability-curated-regression.cjs
node scripts/test-monitor-state-isolation.cjs
