node scripts/test-newest500.cjs
node scripts/test-newest500-pages.cjs
node scripts/test-direct-download.cjs
node scripts/test-stream-component.cjs
node node_modules/typescript/bin/tsc --noEmit
npm run build > "$STAGE/build.log" 2>&1 || { echo "BUILD_FAILED; inspect $STAGE/build.log locally. Public site unchanged."; exit 1; }
cp -a .next/standalone/. "$STAGE/runtime/"
mkdir -p "$STAGE/runtime/.next"
cp -a .next/static "$STAGE/runtime/.next/static"
[[ ! -d public ]] || cp -a public "$STAGE/runtime/public"
cp "$LIVE/.env.production" "$STAGE/runtime/.env.production"
chmod 600 "$STAGE/runtime/.env.production"
mkdir -p "$STAGE/runtime/public"
for marker in "$LIVE"/public/xclip-*-version-*.txt; do [[ ! -f "$marker" ]] || cp "$marker" "$STAGE/runtime/public/"; done
VERSION=xclip-registration-recovery1000-version-20261014.txt
BUILD_ID=$(cat .next/BUILD_ID)
printf '%s\n' "$BUILD_ID" > "$STAGE/runtime/DEPLOY_COMMIT"
printf '%s\n' "$STAGE/source" > "$STAGE/runtime/DEPLOY_SOURCE"
printf '%s\n' "$BUILD_ID" > "$STAGE/runtime/public/$VERSION"
cd "$STAGE/runtime"
PORT=$(node -e 'const s=require("net").createServer();s.listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close();});')
PORT="$PORT" HOSTNAME=127.0.0.1 NODE_ENV=production "$NODE" server.js > "$STAGE/staging-check.log" 2>&1 &
CHECK_PID=$!

READY=0
for attempt in $(seq 1 40); do
 CODE=$(curl -sS --connect-timeout 1 --max-time 3 -o /dev/null -w '%{http_code}' "http://127.0.0.1:$PORT/download" 2>/dev/null) || CODE=000
 if [[ "$CODE" == 200 ]]; then READY=1; break; fi
 kill -0 "$CHECK_PID" 2>/dev/null || { echo 'STAGING_SERVER_EXITED; live unchanged'; exit 1; }
 sleep 1
done
[[ "$READY" == 1 ]] || { echo 'STAGING_START_TIMEOUT; live unchanged'; exit 1; }
BASE="http://127.0.0.1:$PORT" "$NODE" --env-file="$LIVE/.env.production" "$STAGE/installer/verify-endpoints.cjs"
kill "$CHECK_PID" 2>/dev/null || true
wait "$CHECK_PID" 2>/dev/null || true
CHECK_PID=''
BACKUP_BASE=$(mktemp -d "$ACCOUNT/xclip-before-registration-recovery1000-20261014.XXXXXX")
BACKUP="$BACKUP_BASE/runtime"
stop_cwd() {
 local root="$1" pid
 for pid in $(ps -u rbxfxmfd -o pid=,comm= | awk '$2 ~ /^(next-server|node)/ {print $1}'); do
  if [[ "$(readlink "/proc/$pid/cwd")" == "$root" ]]; then kill -TERM "$pid" 2>/dev/null || true; fi
 done
}
rollback() {
 trap - ERR INT TERM
 echo 'REGISTRATION_RECOVERY_DEPLOYMENT_FAILED; restoring previous runtime; settings unchanged'
 set +e
 if [[ -d "$BACKUP" ]]; then
  if [[ -d "$LIVE" ]]; then stop_cwd "$LIVE"; mv "$LIVE" "$BACKUP_BASE/unverified-runtime" || { echo 'ROLLBACK_MOVE_FAILED'; exit 1; }; fi
  mv "$BACKUP" "$LIVE" || { echo 'ROLLBACK_RUNTIME_RESTORE_FAILED'; exit 1; }
  mkdir -p "$LIVE/tmp"; touch "$LIVE/tmp/restart.txt"
 fi
 printf 'ROLLBACK_BACKUP=%s\n' "$BACKUP_BASE"
 local recovered=0 home_code daily_code
 for attempt in $(seq 1 15); do
  home_code=$(curl -sS --connect-timeout 5 --max-time 15 -o /dev/null -w '%{http_code}' "https://xcliprank.com/?rollback=$(date +%s)-$attempt") || home_code=000
  daily_code=$(curl -sS --connect-timeout 5 --max-time 15 -o /dev/null -w '%{http_code}' "https://xcliprank.com/ranking/daily?rollback=$(date +%s)-$attempt") || daily_code=000
  printf 'ROLLBACK_HEALTH_ATTEMPT=%s TOP_HTTP=%s DAILY_HTTP=%s\n' "$attempt" "$home_code" "$daily_code"
  if [[ "$home_code" == 200 && "$daily_code" == 200 ]]; then recovered=1; break; fi
  sleep 2
 done
 if [[ "$recovered" == 1 ]]; then echo 'ROLLBACK_PUBLIC_HEALTH_OK'; else echo 'ROLLBACK_PUBLIC_HEALTH_FAILED; share output for recovery'; fi
 echo 'PREVIOUS_RUNTIME_RESTORED; prior playback/download behavior applies'
 exit 1
}
# Last checks are read-only. Preserve concurrent changes rather than overwriting them.
[[ "$(stat -c %d "$LIVE")" == "$(stat -c %d "$STAGE/runtime")" ]] || { echo 'FILESYSTEM_MISMATCH; live unchanged'; exit 1; }
[[ "$(cat "$LIVE/.next/BUILD_ID")" == "$LIVE_BUILD_ID" ]] || { echo 'LIVE_BUILD_CHANGED_DURING_STAGING; live unchanged'; exit 1; }
cmp -s "$LIVE/.env.production" "$STAGE/source/.env.production" || { echo 'LIVE_ENV_CHANGED_DURING_STAGING; live unchanged'; exit 1; }
